/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_spotIsuTrdMktTpCd", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1' || ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "kclicUsrTpId" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("kclicUsrTpId"))==='CHRG_INST_KRX_STK'); } }, { id: "c_when_49", fn: function(){ return (String(((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId"))).indexOf('CHRG_INST_KRX_') != -1 ||  ((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId")) === 'CHRG_INST_ETC'); } }, { id: "c_otherwise_60", fn: function(){ return (!((String(((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId"))).indexOf('CHRG_INST_KRX_') != -1 ||  ((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId")) === 'CHRG_INST_ETC'))); } }, { id: "c_when_75", fn: function(){ return (String(((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId"))).indexOf('CHRG_INST_KRX_') != -1 ||  ((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId")) === 'CHRG_INST_ETC'); } }, { id: "c_otherwise_86", fn: function(){ return (!((String(((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId"))).indexOf('CHRG_INST_KRX_') != -1 ||  ((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId")) === 'CHRG_INST_ETC'))); } }, { id: "if_notiResult", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "notiResult" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("notiResult"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "notiResult" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("notiResult")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_100", entity: "dlt_notiResult", countIds: [], cells: [{ childId: "btn_goUrl", fn: function (v, i) { return "[가입신청] (" + String(v("etc")) + ") [" + String(v("etc")) + "] " + String(v("title")); } }, { childId: "__rc0", fn: function (v, i) { return " " + String(v("regDate")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.recentKeywrd();
        $("#ipt_formatKeywrd").bind("focus", function() {
                $c.util.getComponent('txt_textSearch').setLabel("");
        });
        $("#ipt_formatKeywrd").bind("focusout", function() {
                if ($(this).val().length == 0) {
                    $c.util.getComponent('txt_textSearch').setLabel("공시 키워드를 입력하십시오.");
                }
        });
        $("#txt_textSearch").bind("click", function() {
                $c.util.getComponent("ipt_formatKeywrd").focus();
        });
        if ($c.util.getComponent('ipt_formatKeywrd').getValue().length == 0) {
            $c.util.getComponent('txt_textSearch').setLabel("공시 키워드를 입력하십시오.");
        }
        for (let i = 0; i < (function(){ throw 'unresolved:list:chgNotiTimer'; })(); i++) {

        }
        confirmF("비밀번호 변경예정일이 ${term}일 남았습니다.\n지금 변경하시겠습니까?", async function() {
                await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /account/mypage.do?method=memberInfoForm). 전환 대상 화면이 확정되면 연결됩니다.');
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods15000.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods15000.onpageload' });
    }
};


