/**
 * @method
 * @name scwin.tx_callAjaxSubmit_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_callAjaxSubmit_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_callAjaxSubmit_ajaxsubmit",
        method: "post",
        action: "/integsrch/findKeywrd.do",
        ref: "dma_callAjaxSubmitAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods15000.tx_callAjaxSubmit_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

